/**
 * Plan Studio API (T084): the structure document of a plan version. Maps get it by hash (the bundle carries only the
 * reference), the historical map by the version's publish timeline; the editor works on the draft through the studio
 * controller.
 */
import { ApiError, apiUrl, get, patch, post, put, resourceUrl, upload, type ApiErrorBody } from './client';
import type { GeomConnector, GeometryDoc, GeomObject, GeomOpening, GeomWall, Pt } from '../map/geometry';
import type { LinkTargetFloor } from '../map/connector-targets';
import type { MapBundle } from './maps';
import type { PlanVersion } from './types';

export interface GeometryRow {
  id: string | null;
  plan_version_id: string;
  floor_id: string;
  status: 'new' | 'draft' | 'published' | 'archived';
  revision: number;
  doc_hash: string;
  created_at: string | null;
  updated_at: string | null;
  published_at: string | null;
  published_by: string | null;
  archived_at: string | null;
}
export interface GeometryIssue {
  code: string;
  severity: 'error' | 'warning';
  structural: boolean;
  id: string | null;
  path: string;
  message: string;
}
export interface CopyCandidate {
  version_id: string;
  status: string;
  created_at: string;
  walls: number;
  openings: number;
  same_drawing: boolean;
}
export interface GeometryResponse {
  geometry: GeometryRow;
  doc: GeometryDoc;
  issues: GeometryIssue[];
  published_hash: string | null;
  copy_candidates?: CopyCandidate[];
  /** PUT only (T085 review M-a): floors whose twin of a changed stair was not updated - no map.edit there. */
  twins_skipped?: { floor_id: string; name: string }[];
  /** CR-009 (owner answer 1), draft reads: the shared rooms' changes a publish of this floor publishes on their home floor. */
  shared_pending?: SharedPending[];
}
/** One home floor whose shared room has changes a publish of this floor would publish there too. `changes` null with
 * `invalid`: the room's content does not validate (the publish reports why). */
export interface SharedPending {
  home_floor_id: string | null;
  home_floor_level?: number | null;
  home_floor_name?: string;
  zone_ids?: string[];
  changes: number | null;
  invalid?: boolean;
  /** invalid: the room's draft items that keep it from validating - a publish can leave them out (`shared_skip`). */
  items?: { id: string; message: string }[];
  message?: string;
}
export interface GeometryDiff {
  collections: Record<string, { added: string[]; removed: string[]; changed: string[] }>;
  total: number;
  calibration_changed: boolean;
  same: boolean;
}
/** Items per collection, as the server counts them. */
export interface GeometryCounts {
  walls: number;
  openings: number;
  labels: number;
  objects: number;
  connectors: number;
  circuits: number;
  levels: number;
  groups: number;
}
/** GET /plan-versions/{id}/geometry/diff: the draft against the published structure, the draft's issues and the counts
 * before and after (published_counts is null before the first publish). */
export interface GeometryDiffResponse {
  diff: GeometryDiff;
  issues: GeometryIssue[];
  counts: GeometryCounts;
  published_counts: GeometryCounts | null;
  shared_pending?: SharedPending[];
}
export interface CalibrationResult {
  version: PlanVersion;
  scale_m_per_px: number;
  residual_pct: number | null;
  warning: string | null;
  /** "measured" (two-point pairs) or "estimated" (the door-width hint, phase 3). */
  status?: 'measured' | 'estimated';
}
export interface GeometryPeriod {
  id: string;
  doc_hash: string;
  published_at: string;
  archived_at: string | null;
}

const byHash = new Map<string, GeometryDoc>();
const timelines = new Map<string, Promise<GeometryPeriod[]>>();

export function getGeometry(versionId: string, opts: { draft?: boolean; at?: string } = {}): Promise<GeometryResponse> {
  const q = new URLSearchParams();
  if (opts.draft) q.set('draft', 'true');
  if (opts.at) q.set('at', opts.at);
  const qs = q.toString();
  return get<GeometryResponse>(`plan-versions/${versionId}/geometry${qs ? `?${qs}` : ''}`);
}

/** The structure a live map shows: fetched once per hash. A map without its structure still works (null on error). */
export async function geometryFor(bundle: MapBundle): Promise<GeometryDoc | null> {
  const ref = bundle.geometryRef;
  if (bundle.source !== 'api' || !ref || !bundle.planVersionId) return null;
  // CR-009: a floor that shows a room of another floor (or shares one of its own) is keyed by its view hash, which moves
  // when the other floor changes; the document's own hash does not
  const key = ref.view_hash ?? ref.doc_hash;
  const hit = byHash.get(key);
  if (hit) return hit;
  try {
    // A published or archived row is asked for by its publish instant, so an exact-history bundle gets the row it names.
    // CR-009: with shared rooms the instant matters beyond this floor's own row - an exact-history bundle asks for its own
    // instant (the rooms shared then, as their home floors were then), the live map for the current structure.
    const opts = ref.status === 'draft' ? { draft: true } : ref.view_hash ? (bundle.history === 'exact' && bundle.at ? { at: bundle.at } : {}) : ref.published_at ? { at: ref.published_at } : {};
    const r = await getGeometry(bundle.planVersionId, opts);
    byHash.set(key, r.doc);
    return r.doc;
  } catch {
    return null;
  }
}

/** The structure a historical map shows at an instant: the version's publish timeline is read once, documents once per hash. */
export async function geometryAt(versionId: string, iso: string): Promise<GeometryDoc | null> {
  let tl = timelines.get(versionId);
  if (!tl) {
    const fetched: Promise<GeometryPeriod[]> = get<{ timeline: GeometryPeriod[] }>(`plan-versions/${versionId}/geometry/timeline`)
      .then((r) => r.timeline)
      .catch(() => {
        if (timelines.get(versionId) === fetched) timelines.delete(versionId); // a failed read is not remembered: the next move asks again
        return [];
      });
    tl = fetched;
    timelines.set(versionId, tl);
  }
  const period = (await tl).find((p) => p.published_at <= iso && (!p.archived_at || iso < p.archived_at));
  if (!period) return null;
  const hit = byHash.get(period.doc_hash);
  if (hit) return hit;
  try {
    const r = await getGeometry(versionId, { at: period.published_at });
    byHash.set(r.geometry.doc_hash, r.doc);
    return r.doc;
  } catch {
    return null;
  }
}

export const saveGeometryDraft = (versionId: string, doc: GeometryDoc, baseRevision: number) =>
  put<GeometryResponse>(`plan-versions/${versionId}/geometry`, { doc, base_revision: baseRevision });
/** A publish changes the version's timeline: the cached one is dropped (documents stay cached by hash), so an open
 * historical map shows the new structure at instants after it. */
export async function publishGeometry(versionId: string, sharedSkip: string[] = []): Promise<{ published: GeometryRow | null; diff: GeometryDiff; unchanged: boolean; shared_published?: { home_floor_id: string; zone_ids: string[]; changes: number }[] }> {
  const r = await post<{ published: GeometryRow | null; diff: GeometryDiff; unchanged: boolean; shared_published?: { home_floor_id: string; zone_ids: string[]; changes: number }[] }>(
    `plan-versions/${versionId}/geometry/publish`, sharedSkip.length ? { shared_skip: sharedSkip } : undefined);
  timelines.delete(versionId);
  return r;
}
export const geometryDiff = (versionId: string) => get<GeometryDiffResponse>(`plan-versions/${versionId}/geometry/diff`);
/** K88 (editor leftover): every published structure of the version, newest first, with what each held. */
export interface GeometryVersionRow extends GeometryRow {
  counts: Record<string, number>;
}
export const listGeometryVersions = (versionId: string) => get<{ versions: GeometryVersionRow[] }>(`plan-versions/${versionId}/geometry/versions`);
/** Publish an archived structure again as a new published copy (the history is never deleted); map.publish. */
export async function rollbackGeometry(versionId: string, geometryId: string) {
  const r = await post<{ published: GeometryRow }>(`plan-versions/${versionId}/geometry/rollback`, { geometry_id: geometryId });
  timelines.delete(versionId);
  return r;
}
export const copyGeometryFrom = (versionId: string, fromVersionId: string) =>
  post<GeometryResponse>(`plan-versions/${versionId}/geometry/copy-from`, { from_version_id: fromVersionId });
export const calibrate = (versionId: string, pairs: { a: Pt; b: Pt; metres: number }[]) =>
  patch<CalibrationResult>(`plan-versions/${versionId}/calibration`, { pairs });
export function exportUrl(versionId: string, fmt: 'svg' | 'png' | 'dxf' | 'ifc', opts: { draft?: boolean; layers?: string[] } = {}): string {
  const q = new URLSearchParams();
  if (opts.draft) q.set('draft', 'true');
  if (opts.layers?.length) q.set('layers', opts.layers.join(','));
  const qs = q.toString();
  return resourceUrl(`api/v1/plan-versions/${versionId}/export.${fmt}${qs ? `?${qs}` : ''}`);
}
