const packageForm = (file: File | Blob) => {
  const form = new FormData();
  form.set('file', file, file instanceof File && file.name ? file.name : 'plan.swplan.zip');
  return form;
};
/** The signed package of the draft (or the published structure) as a file to save; map.edit. `dxf` (PLN2): the package
 * also carries assets/plan.dxf beside the plan picture its IMAGE names (an importer before PLN2 refuses that file). */
export async function exportPlanPackage(versionId: string, draft: boolean, opts: { dxf?: boolean } = {}): Promise<{ blob: Blob; name: string }> {
  const res = await fetch(apiUrl(`plan-versions/${versionId}/package`), {
    method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(opts.dxf ? { draft, dxf: true } : { draft }),
  });
  if (!res.ok) {
    let body: ApiErrorBody;
    try {
      body = (await res.json()) as ApiErrorBody;
    } catch {
      body = { code: `http_${res.status}`, user_message: res.statusText, retryable: false, correlation_id: '', details: {} };
    }
    throw new ApiError(res.status, body);
  }
  const cd = res.headers.get('content-disposition') ?? '';
  const name = /filename="([^"]+)"/.exec(cd)?.[1] ?? `plan-${versionId}.swplan.zip`;
  return { blob: await res.blob(), name };
}
/** The dry run of an import: nothing is written. */
/** A package signed by another system (or by a retired key of this one) answers 409 `package_foreign` with
 * `details.origin` until the person trusts it and the preview is asked again with `acceptForeign` (security review 2.2.0). */
export const previewPlanPackage = (versionId: string, file: File | Blob, mode: PackageMode, acceptForeign = false) =>
  upload<PackagePreview>(`plan-versions/${versionId}/package/preview?mode=${mode}${acceptForeign ? '&accept_foreign=true' : ''}`, packageForm(file));
/** The import itself, into the draft: the revision and the result hash the preview showed. */
export const importPlanPackage = (versionId: string, file: File | Blob, preview: PackagePreview, acceptForeign: boolean) =>
  upload<PackageImportResult>(
    `plan-versions/${versionId}/package/import?mode=${preview.mode}&base_revision=${preview.base_revision}&expect_hash=${preview.result_hash}${acceptForeign ? '&accept_foreign=true' : ''}`,
    packageForm(file),
  );
/** Stairs / an elevator to another floor: the same connector id lands on the other floor's draft (T085). */
/** Link a connector to another floor (T085): `levelTo` is the level it reaches THERE (absent = that floor's default).
 * placement: the new twin sits at the same plan coordinates (aligned), at the other plan's centre (centred - it waits to
 * be placed) or an existing twin kept its own position (kept). */
export const linkConnector = (versionId: string, connectorId: string, floorId: string, levelTo?: string | null, replace = false) =>
  post<{ connector: GeomConnector; removed_floors: string[]; target: { floor_id: string; version_id: string; revision: number; level_id: string; placement: 'aligned' | 'centred' | 'kept'; frame: 'sheet' | 'size' | null } }>(
    `plan-versions/${versionId}/geometry/link`, { connector_id: connectorId, floor_id: floorId, ...(levelTo ? { level_to: levelTo } : {}), ...(replace ? { replace: true } : {}) });

/** The other floors of the building a connector can reach, each with its levels (the "מחבר אל" picker). */
export const getLinkTargets = (versionId: string) => get<{ floors: LinkTargetFloor[] }>(`plan-versions/${versionId}/geometry/link-targets`);

/** Remove the twin of a cross-floor connector from the other floor's draft ("למחוק גם בקומה השנייה?"). */
export const deleteTwin = (versionId: string, connectorId: string, floorId: string) =>
  post<{ removed: boolean; floor_id: string }>(`plan-versions/${versionId}/geometry/twin-delete`, { connector_id: connectorId, floor_id: floorId });

// ---------------------------------------------------------------- detection (phase 3, T086)

export type DetectTarget = 'walls' | 'openings';
export interface DetectRequest {
  targets?: DetectTarget[];
  /** 0.3 (light morphology) to 1.0 (strong); the server's default is 0.6. */
  strength?: number;
  level_id?: string;
  /** T087: the hollow-wall pass (walls drawn as two thin lines); the server's default is on, false opts a plan out. */
  hollow_walls?: boolean;
  /** Detector 1.4 (T086 tuning), each on by default, false opts a plan out: section-cut lines crossing the envelope
   * are no walls; a white gap under 0.3 m with no symbol is one wall (no passage); a tribune is proposed as a steps
   * object; a pier grid as column objects with the envelope line between them. */
  section_lines?: boolean;
  join_gaps?: boolean;
  steps_regions?: boolean;
  columns?: boolean;
}
export interface CalibrationHint {
  scale_m_per_px: number;
  status: 'estimated';
  method: 'door_width';
  reason: string;
  doors: number;
}
/** Version pixels per candidate: the client recomputes the metres with the document's effective scale before accepting. */
export type CandidatePixels = Record<string, { thickness_px?: number; width_px?: number; w_px?: number; d_px?: number }>;
export interface DetectorInfo {
  name: string;
  version: string;
  params: Record<string, unknown>;
}
export interface DxfRoomCandidate {
  polygon: { x: number; y: number }[];
  name: string;
}
/** Plan Studio 8 (CR-037): the report of an IFC import - what was read for the chosen storey, what was skipped and
 * why (a partial import is never silent), the file's storeys and how the model was aligned to the plan. */
export interface IfcImportReport {
  schema: string;
  entities: number;
  metres_per_unit: number;
  ms: number;
  storeys: { index: number; name: string; elevation_m: number; chosen: boolean }[];
  counts: { walls: number; openings: number; objects: number; rooms: number };
  skipped: { id: string; class: string; reason: string; name: string }[];
  skipped_total: number;
  skipped_by_reason: Record<string, number>;
  warnings: string[];
  alignment: { dx_m: number; dy_m: number; fits: boolean; needed_m: [number, number] | null; plan_m: [number, number] };
}
/** POST /plan-versions/{id}/detect and POST …/import-dxf-geometry: candidates in document-v2 shape, never stored.
 * Deviation from the brief (API review): object candidates are document-v2 objects (GeomObject), not the brief's
 * pose/catalog_id shape - the backend never produced that shape (services/plan_geometry.py merge_candidates,
 * CANDIDATE_COLLECTIONS includes "objects" with the same schema _check_objects validates). */
export interface DetectResult {
  walls: GeomWall[];
  openings: GeomOpening[];
  /** The DXF import's mapped blocks; since detector 1.4 also /detect's tribunes and columns (source "auto", their
   * width / depth in version pixels in `pixels` as w_px / d_px). */
  objects?: GeomObject[];
  rooms?: DxfRoomCandidate[];
  detector: DetectorInfo;
  calibration_hint: CalibrationHint | null;
  pixels: CandidatePixels;
  /** Deviation from the brief (API review, matches services/plan_detect.py): "estimated_walls", not "estimated" -
   * an uncalibrated detect always answers this even when the version's own calibration is an estimate; the "≈" on
   * screen comes from the document's effective scale (map/geometry.ts effectiveScale), never from this field. */
  scale: { m_per_px: number | null; status: 'measured' | 'estimated' | 'estimated_walls' };
  stats: Record<string, number>;
  /** Detector 1.2 (T087 review): wall candidates kept although they lie outside the main structure (a small building
   * beside a large one) - listed so the person reviewing sees them; absent from older detectors and the DXF import. */
  flags?: { outside_main: string[] };
  version_id: string;
  level_id: string;
  /** Items of the candidates' source already in the draft; `objects` comes with the DXF import (and a newer /detect). */
  existing_auto: { walls: number; openings: number; objects?: number };
  elapsed_ms?: number;
  /** The IFC import's report (CR-037); absent from /detect and the DXF import. */
  ifc?: IfcImportReport;
}
export interface AcceptRequest {
  accepted: string[];
  /** A partial object/wall/opening (document-v2 fields only): the server accepts only the editable fields of each
   * collection (services/plan_geometry.py EDITABLE_FIELDS) and ignores the rest - id, source and confidence never
   * travel through an edit. */
  edits: Record<string, Partial<GeomWall> | Partial<GeomOpening> | Partial<GeomObject>>;
  replace_auto: boolean;
  candidates: { walls: GeomWall[]; openings: GeomOpening[]; objects?: GeomObject[] };
  base_revision: number;
  detector: DetectorInfo | null;
}
export const detectStructure = (versionId: string, body: DetectRequest) => post<DetectResult>(`plan-versions/${versionId}/detect`, body);
/** What the merge did (services/plan_geometry.py merge_candidates): with replace_auto the draft's earlier items of the
 * candidates' source went first (`removed_auto`), and the openings of another source that sat on a removed wall went
 * with it (`removed_manual_openings`); `reided` counts accepted ids that collided with the draft and were re-issued as
 * plain ids (so nothing may key on the "auto-" / "imp-" prefix). Optional: a server without it answers the bare payload. */
export interface AcceptMerge {
  accepted: { walls: number; openings: number; objects: number };
  removed_auto: number;
  removed_manual_openings: number;
  reided: number;
}
/** The accept answer is the draft as a save answers it (revision, hash, document, issues), plus the merge counts. */
export interface AcceptResponse extends GeometryResponse {
  merge?: AcceptMerge;
}
export const acceptDetection = (versionId: string, body: AcceptRequest) => post<AcceptResponse>(`plan-versions/${versionId}/detect/accept`, body);
/** The door-width hint as an estimated calibration (design 6.3): metres then show with "≈". The server refuses an
 * estimate over a measured calibration (409 calibration_measured) unless `replaceMeasured` confirms it; the editor
 * never sends it (it offers the estimate only while the calibration is not measured). */
export const calibrateEstimate = (versionId: string, scaleMPerPx: number, reason: string, replaceMeasured?: boolean) =>
  patch<CalibrationResult>(`plan-versions/${versionId}/calibration`, {
    estimate: { scale_m_per_px: scaleMPerPx, method: 'door_width', reason },
    ...(replaceMeasured === undefined ? {} : { replace_measured: replaceMeasured }),
  });

/** POST /plan-versions/{id}/door-proposal (T087, the "סמן דלת" tool): what the local analysis proposes for one click -
 * services/plan_door_tool.py. Never stored: the editor adds it to the draft as an ordinary opening once accepted. */
export type DoorFound = 'arc' | 'chord' | 'leaf' | 'double' | 'gap' | 'default';
export interface DoorProposalRequest {
  x: number;
  y: number;
  wall_id?: string;
  level_id?: string;
}
export interface DoorProposal {
  found: DoorFound;
  /** Hebrew, short: "נמצאה קשת" / "נמצא פער" / "ברירת מחדל - בדוק" ... */
  note: string;
  /** The draft wall the door goes on; null when the proposal brings a wall piece of its own (`new_wall`). */
  wall_id: string | null;
  t: number;
  new_wall: { polyline: [number, number][]; thickness_px: number } | null;
  /** Version pixels: the client turns them into metres with the document's effective scale. null = the default width. */
  width_px: number | null;
  hinge: 'start' | 'end';
  swing: 'left' | 'right' | 'double';
  confidence: number;
  warning: string | null;
  elapsed_ms: number;
  version_id: string;
  level_id: string;
}
export const proposeDoor = (versionId: string, body: DoorProposalRequest) => post<DoorProposal>(`plan-versions/${versionId}/door-proposal`, body);

/** Error codes /detect, /detect/accept and /calibration (estimate) can answer with (the API review, backed by
 * routers/plan_geometry.py and tests/test_plan_detect_api.py): the client reads them off ApiError.code. detect_timeout
 * (504) is retryable. calibration_measured (409, "an estimate never replaces a measured calibration silently"): the
 * editor offers the estimate only while the calibration is not measured and never sends replace_measured (Task 9). */
export type DetectErrorCode = 'detect_timeout' | 'stale_revision' | 'calibration_measured' | 'unknown_candidate' | 'orphan_opening' | 'candidate_source' | 'duplicate_candidate' | 'candidate_shape' | 'geometry_structure';

export type DxfTarget = 'walls' | 'openings' | 'windows' | 'objects' | 'rooms' | 'ignore';
export interface DxfEntityLayer {
  name: string;
  count: number;
  kinds: Record<string, number>;
  sample: string;
  suggested: DxfTarget;
  in_render: boolean;
}
export interface DxfBlock {
  name: string;
  count: number;
  size_m: [number, number];
  suggested: { catalog_id: string | null; name: string };
}
export interface DxfEntities {
  asset_id: string;
  units: string;
  metres_per_unit: number | null;
  layers: DxfEntityLayer[];
  blocks: DxfBlock[];
  targets: { id: DxfTarget; label: string }[];
  catalog_choices: { id: string | null; name: string }[];
}
export const getDxfEntities = (assetId: string) => get<DxfEntities>(`plan-assets/${assetId}/dxf/entities`);
export const importDxfGeometry = (versionId: string, body: { layer_map: Record<string, DxfTarget>; block_map: Record<string, string | null>; level_id?: string }) =>
  post<DetectResult>(`plan-versions/${versionId}/import-dxf-geometry`, body);
/** POST /plan-versions/{id}/import-ifc (CR-037): the file's candidates for one document level in the shape of /detect
 * plus the report under `ifc`; nothing is stored (the accept goes through /detect/accept). map.import. */
export function importIfcGeometry(versionId: string, file: File | Blob, opts: { levelId?: string; storey?: number } = {}): Promise<DetectResult> {
  const q = new URLSearchParams();
  if (opts.levelId) q.set('level_id', opts.levelId);
  if (opts.storey !== undefined) q.set('storey', String(opts.storey));
  const form = new FormData();
  form.append('file', file, file instanceof File ? file.name : 'plan.ifc');
  const qs = q.toString();
  return upload<DetectResult>(`plan-versions/${versionId}/import-ifc${qs ? `?${qs}` : ''}`, form);
}
